package week_01;
import javax.swing.*;import java.awt.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;
public final class FileTextIO {private FileTextIO(){} public static String open(Component p,JTextArea a){JFileChooser c=new JFileChooser();if(c.showOpenDialog(p)!=JFileChooser.APPROVE_OPTION)return null;try{a.setText(Files.readString(c.getSelectedFile().toPath(),StandardCharsets.UTF_8));return c.getSelectedFile().getAbsolutePath();}catch(IOException e){JOptionPane.showMessageDialog(p,e.getMessage());return null;}}public static String save(Component p,JTextArea a,String name){JFileChooser c=new JFileChooser();c.setSelectedFile(new File(name));if(c.showSaveDialog(p)!=JFileChooser.APPROVE_OPTION)return null;try{Files.writeString(c.getSelectedFile().toPath(),a.getText(),StandardCharsets.UTF_8);return c.getSelectedFile().getAbsolutePath();}catch(IOException e){JOptionPane.showMessageDialog(p,e.getMessage());return null;}}}
